258			`{"op":"query","name":"m","start":0,"end":10,"labels":{"host":"a","\u0068ost":"b"}}`, // 值不同
259		} {
260			_, lerr := store.QueryLine(q)
261			if lerr == nil {
262				t.Fatalf("query %s must fail on escaped duplicate label key", q)
263			}
264			if lerr.Index != 0 || lerr.Conflict != nil {
