266			}
267			if !strings.Contains(lerr.Error, `duplicate label key "host"`) {
268				t.Fatalf("query %s: error = %q, want duplicate label key host", q, lerr.Error)
269			}
270		}
271	
272		// 绝不能把重复标签条件当成两个标签去匹配：合法查询结果保持不变。
273		qr := mustQuery(t, store, `{"op":"query","name":"m","start":0,"end":10,"labels":{"host":"a"}}`)
274		if len(qr.Series) != 1 || qr.Series[0].Average != 3 {
275			t.Fatalf("storage/read path must be unaffected, got %+v", qr.Series)
276		}
277	}
