222			{`[{"name":"m","timestamp":9223372036854775808,"value":1}]`, 1},          // timestamp 超 int64
223			{`[{"name":"m","timestamp":-9223372036854775809,"value":1}]`, 1},         // timestamp 低于 int64
224			{`[{"name":"m","timestamp":1,"value":1,"zone":"x"}]`, 1},                 // 未知字段
225			{`[{"name":"m","timestamp":1,"value":1,"labels":[]}]`, 1},                // labels 非对象
226			{`[{"name":"m","timestamp":1,"value":1,"labels":null}]`, 1},              // labels 为 null
