657		// 精确平均恰为 2^-1075（0 与最小次正规值正中）：按最近偶数舍入为 0。
658		store2 := NewMetricStore()
659		mustOK(t, store2, `[
660			{"name":"m","timestamp":1,"value":5e-324},
661			{"name":"m","timestamp":2,"value":0}
662		]`)
663		res = mustQuery(t, store2, `{"op":"query","name":"m","start":0,"end":10}`)
664		if avg := res.Series[0].Average; avg != 0 {
665			t.Fatalf("tie at 2^-1075 must round to even (0), got %v", avg)
666		}
667	
668		// 单点序列返回该点的值本身。
669		store3 := NewMetricStore()
670		mustOK(t, store3, `[{"name":"m","timestamp":7,"value":0.1}]`)
671		res = mustQuery(t, store3, `{"op":"query","name":"m","start":0,"end":10}`)
672		if avg := res.Series[0].Average; avg != 0.1 {
673			t.Fatalf("single point average = %v, want 0.1", avg)
674		}
675	}
676	
677	func TestQueryValidationErrors(t *testing.T) {
678		store := NewMetricStore()
679		mustOK(t, store, `[{"name":"m","timestamp":1,"value":1}]`)
680		bad := []string{
681			`{"op":"query","name":"","start":0,"end":1}`,                                        // 空 name
682			`{"op":"query","name":7,"start":0,"end":1}`,                                         // name 类型错误
683			`{"op":"query","name":"m","start":0}`,                                               // 缺 end
684			`{"op":"query","name":"m","start":0,"end":1,"extra":1}`,                             // 未知字段
685			`{"op":"ingest","name":"m","start":0,"end":1}`,                                      // 未知 op
686			`{"op":"write","name":"m","start":0,"end":1}`,                                       // 其他 op
687			`{"op":7,"name":"m","start":0,"end":1}`,                                             // op 类型错误
688			`{"op":"query","op":"query","name":"m","start":0,"end":1}`,                          // 重复字段
689			`{"op":"query","name":"m","start":0.5,"end":1}`,                                     // start 非整数
690			`{"op":"query","name":"m","start":"0","end":1}`,                                     // start 字符串
691			`{"op":"query","name":"m","start":true,"end":1}`,                                    // start 布尔
692			`{"op":"query","name":"m","start":0,"end":9223372036854775808}`,                     // end 超 int64
693			`{"op":"query","name":"m","start":2,"end":1}`,                                       // start > end
694			`{"op":"query","name":"m","start":-9223372036854775808,"end":-9223372036854775809}`, // end 低于 int64
695			`{"op":"query","name":"m","start":0,"end":1,"labels":[]}`,                           // labels 非对象
696			`{"op":"query","name":"m","start":0,"end":1,"labels":null}`,                         // labels 为 null
697			`{"op":"query","name":"m","start":0,"end":1,"labels":{"":"v"}}`,                     // 空标签键
698			`{"op":"query","name":"m","start":0,"end":1,"labels":{"k":1}}`,                      // 标签值非字符串
699			`{"op":"query","name":"m","start":0,"end":1,"labels":{"k":"a","k":"b"}}`,            // 重复标签键
700			`{"name":"m","start":0,"end":1}`,                                                    // 缺 op
701			`{"op":"query","start":0,"end":1}`,                                                  // 缺 name
702			`{"op":"query","name":"m","start":0,"end":1} trailing`,                              // 尾随内容
703		}
704		for _, line := range bad {
705			lerr := mustQueryFail(t, store, line)
706			if lerr.Index != 0 {
707				t.Errorf("line %s: query errors must not carry index, got %d", line, lerr.Index)
708			}
709			if lerr.Conflict != nil {
710				t.Errorf("line %s: query errors must not carry conflict", line)
711			}
712		}
713		// 非法行不改变存储。
714		res := mustQuery(t, store, `{"op":"query","name":"m","start":0,"end":100}`)
715		if len(res.Series) != 1 || res.Series[0].Count != 1 {
716			t.Fatalf("failed queries must not mutate storage, got %+v", res.Series)
717		}
718	}
719	
720	func TestProcessLineDispatchesArrayAndObject(t *testing.T) {
721		store := NewMetricStore()
722		r, lerr := store.ProcessLine(`[{"name":"m","timestamp":1,"value":2}]`)
723		if lerr != nil {
724			t.Fatalf("array line: %+v", lerr)
725		}
726		if _, ok := r.(*BatchResult); !ok {
727			t.Fatalf("array line result type = %T, want *BatchResult", r)
728		}
729		r, lerr = store.ProcessLine(`{"op":"query","name":"m","start":0,"end":10}`)
730		if lerr != nil {
731			t.Fatalf("object line: %+v", lerr)
732		}
733		qr, ok := r.(*QueryResult)
734		if !ok {
735			t.Fatalf("object line result type = %T, want *QueryResult", r)
736		}
737		if len(qr.Series) != 1 || qr.Series[0].Average != 2 {
738			t.Fatalf("query via ProcessLine = %+v", qr)
739		}
740		// 标量顶层值仍然是整行错误，且不带 index。
741		_, lerr = store.ProcessLine(`"hello"`)
742		if lerr == nil || lerr.Index != 0 {
743			t.Fatalf("scalar line = %+v, want whole-line error without index", lerr)
744		}
745		_, lerr = store.ProcessLine(`{}`)
746		if lerr == nil {
747			t.Fatal("empty object must fail validation")
